#include "system_integration.hpp"
namespace sys {
std::wstring text(HWND h) { int n = GetWindowTextLengthW(h); std::wstring v(n + 1, L'\0'); if (n) GetWindowTextW(h, v.data(), n + 1); v.resize(n); return v; }
bool startupEnabled() { HKEY k; if (RegOpenKeyExW(HKEY_CURRENT_USER, L"Software\\Microsoft\\Windows\\CurrentVersion\\Run", 0, KEY_QUERY_VALUE, &k) != ERROR_SUCCESS) return false; LONG ok = RegQueryValueExW(k, L"CleanText", nullptr, nullptr, nullptr, nullptr); RegCloseKey(k); return ok == ERROR_SUCCESS; }
void setStartup(app::AppState& s, bool enabled) { HKEY k; if (RegCreateKeyExW(HKEY_CURRENT_USER, L"Software\\Microsoft\\Windows\\CurrentVersion\\Run", 0, nullptr, 0, KEY_SET_VALUE, nullptr, &k, nullptr) != ERROR_SUCCESS) return; if (enabled) { wchar_t path[MAX_PATH]; GetModuleFileNameW(nullptr, path, MAX_PATH); std::wstring command = L"\"" + std::wstring(path) + L"\""; RegSetValueExW(k, L"CleanText", 0, REG_SZ, reinterpret_cast<const BYTE*>(command.c_str()), DWORD((command.size()+1)*sizeof(wchar_t))); } else RegDeleteValueW(k, L"CleanText"); RegCloseKey(k); s.startup = startupEnabled(); }
void copyResult(app::AppState& s) { if (s.result.empty()) return; for (int i=0; i<4; ++i) if (OpenClipboard(s.hwnd)) { EmptyClipboard(); size_t bytes=(s.result.size()+1)*sizeof(wchar_t); HGLOBAL mem=GlobalAlloc(GMEM_MOVEABLE, bytes); if (mem) { memcpy(GlobalLock(mem), s.result.c_str(), bytes); GlobalUnlock(mem); SetClipboardData(CF_UNICODETEXT, mem); } CloseClipboard(); s.copied=true; SetTimer(s.hwnd, 1, 1200, nullptr); InvalidateRect(s.hwnd, nullptr, FALSE); return; } }
}
